'use strict';

var multiformats = require('multiformats');
var sha2 = require('./sha2-DPMm-Wnq.cjs');
var raw = require('./raw-0W-AUXof.cjs');
require('crypto');

function isValidCID(cid) {
    try {
        multiformats.CID.parse(cid);
        return true;
    }
    catch (error) {
        return false;
    }
}
function isValidDID(did) {
    if (typeof did !== 'string') {
        return false;
    }
    if (!did.startsWith('did:')) {
        return false;
    }
    const parts = did.split(':');
    if (parts.length < 3) {
        return false;
    }
    const suffix = parts.pop();
    return isValidCID(suffix);
}
async function generateCID(data) {
    let buf;
    let code;
    if (typeof data === 'string') {
        buf = new TextEncoder().encode(data);
        code = raw.code;
    }
    else if (data instanceof Buffer) {
        buf = data;
        code = raw.code;
    }
    else {
        buf = sha2.encode(data);
        code = sha2.code;
    }
    const hash = await sha2.sha256.digest(buf);
    const cid = multiformats.CID.createV1(code, hash);
    return cid.toString(); // CID v1 default: base32 encoding
}

exports.generateCID = generateCID;
exports.isValidCID = isValidCID;
exports.isValidDID = isValidDID;
